INSERT INTO settlements (settlement_id, name, type, culture_id, faction_id, lord_id, prosperity, description) VALUES
  ('askar', 'Askar', 'Town', 1, 'aserai', 'Iyalas', 2100.0, 'Askar dominates the middle stretches of the Damar River, as it weaves between the bluffs of the Jarjara Escarpment. This region has been thickly populated for thousands of years, but the river is restless, and every few centuries leaps its banks and erases what comes before. This latest regional capital was an imperial encampment during their furthest penetration of the Nahasa Desert several centuries ago, taken over by the Aserai tribes after the legions withdrew. [1]'),
  ('hubyar', 'Hubyar', 'Town', 1, 'aserai', 'Tais', 3200.0, 'The inland city of Hubyar is said to be built on the ruins of a luxurious hunting lodge built by the decadent and cruel king Thuran, whom the patriarch Asera slew in vengeance for the enslavement of his family. This memory may explain the worldview of the fierce and austere Banu Qild, who hold the castle today and who detest all frivolity. But the scent of jasmine that can be detected on the night breezes here carry an undercurrent of temptation. It was here that the hero Nimr came to grief, caught in the chamber of a Banu Qild maiden and left hanging in a cage in the market until he perished.[1]'),
  ('husn_fulq', 'Husn Fulq', 'Town', 1, 'aserai', 'Adram', 4200.0, 'Husn Fulq sits at the southeastern edge of the Calsea, the network of rivers and brackish lagoons linking the Empire to the Aserai lands. Fulq, also known as Phalcos, was a dark-faced mercenary chieftain who came from lands far to the south. He founded a fortress here and then parlayed its strategic location into a forture, taking bribes from the Empire and then from the Aserai to switch sides. After 20 years of playing both sides back and forth he sailed home in a ship laden with gold, but many clans of the Aserai proudly claim descent from him, and the ''Tricks of Fulq'' are a staple of many a bazaar storyteller''s repertoire.[1]'),
  ('iyakis', 'Iyakis', 'Town', 1, 'aserai', 'Suruq', 1800.0, 'Iyakis sits in a cleft in the Jarjara Escarpment, where the waters of the fierce but brief desert rains can be trapped and used for irrigation. Several generations ago it was an autonomous outpost of the Empire known as Yachios, dominated by the Carasios clan. Fifty years ago however they saw the writing on the wall for imperial dominion in the southlands and began intermarrying themselves with the tribes of the Nahasa. Today, known as the Qaraz, they take their places in the councils of the sultanate like any other family of the Aserai.[1]'),
  ('qasira', 'Qasira', 'Town', 1, 'aserai', 'Talas', 3500.0, 'Qasira is a town of the Aserai ruled by Emir Talas of the Banu Atij. The villages of Ezbet Nahul and Abghan are bound to the town.'),
  ('quyaz', 'Quyaz', 'Town', 1, 'aserai', 'Unqid', 4000.0, 'Quyaz was once a mercantile republic that dominated the trade between the western ocean and the Perassic Sea, speaking the now all-but-extinct Kannic tongue, a relative of the Nahasi language. But imperial hegemony slowly snuffed out its trade, and the ruler was taken over by mercenaries from the Nahasi tribes. It came intermittently under imperial subjugation but today is a prized holding of the Banu Hulyan, a leading clan of the Aserai Sultanate.[1]'),
  ('razih', 'Razih', 'Town', 1, 'aserai', 'Adram', 4500.0, 'Razih is said to be the base from which Kannic explorers set forth to colonize the shores of the Perassic Sea in the centuries before the coming of the Empire, the prows of their ships decorated with the intertwined vine leaves of the Kannic goddess of wealth, wine, love, and war. Today, the Kannic tongue has been replaced by Nahasi dialects and their religion is all but forgotten, but the symbol lives on, said to protect those who risk all for the sake of gain or glory.[1]'),
  ('sanala', 'Sanala', 'Town', 1, 'aserai', 'Unqid', 4300.0, 'The port of Sanala is the gateway through which the grain of the Damar River has flowed forth to feed a hungry world. The Empire''s periodic advances south of the Perassic Sea have usually been aimed at seizing this strategic prize. Although the legions were long ago been forced to retreat, Sanala remains among the most cosmopolitan cities in Calradia, filled with merchants from many lands bidding for the lowest bulk prices.[1]'),
  ('car_banseth', 'Car Banseth', 'Town', 2, 'battania', 'Melidir', 2200.0, 'Car Banseth sits high on the cliffs of Ailta Druin. Staring north on a clear day, across lands that were once battanian but are now held by the strugia and vlandias, one can see the waters of the Bay of Varcheg. It is said that those who keep faith will one day witness from this high point the ships of the vanished High King Mon, who shall return to deliver his people from their enemies. But today, one is far more likely to see the sails of Nordic adventurers and mercenaries, coming to assist the foreigners in their relentless push into 2n land.'),
  ('dunglanys', 'Dunglanys', 'Town', 2, 'battania', 'Ergeon', 4000.0, 'Dunglanys, the ''Rock of Glanys'', stands on a high crag overlooking the Llyn Tywal, the pool of darkness at the heart of the battanian lands. It was named after an ancient queen who, legend has it, married in succession five high kings of Battanian, bestowing sovereignty upon them. It is the center of the rituals that underpin 2n kingship, and though not every 2n high king has ruled from here, all are eager to hold it.'),
  ('marunath', 'Marunath', 'Town', 2, 'battania', 'Caladog', 5000.0, 'Marunath is a town of the Kingdom of Battania, ruled by High King Caladog of clan fen Gruffendoc.'),
  ('pen_cannoc', 'Pen Cannoc', 'Town', 2, 'battania', 'Aeron', 3800.0, 'Pen Cannoc sits on a promontory overlooking the Trand river as it plunges from the Uchalion plateau into the 7n lowlands. Legends speak of the water-nymphs who live in the dark pools under the rock, luring travellers and invaders to their deaths except on those rare occasions when they fall in love with a hero and grant him victory and blessings. Certainly the fisherfolk of this region have learned respect for the perils of the upper Trand, where a small misstep on slippery stone can cast one off a precipice into the waters below.'),
  ('seonon', 'Seonon', 'Town', 2, 'battania', 'Luichan', 2400.0, 'Seonon, sad Seonon, has a history as dark as the waters of the Llyn Tywal. Here Algana the Fair stood atop the tower lamenting the death of her beloved Gorawan, until the spirits of the Otherworld were themselves overcome with sadness and allowed his shade to ascend through the pool for a day and a night to console her. In latter days this land has often been ravaged by 6n raiders, and not far from here lies the wood where King Aeril disappeared, clearing the way for the rise of Caladog.'),
  ('akkalat', 'Akkalat', 'Town', 4, 'khuzait_khanate', 'Hurunag', 1700.0, 'The town that the Khuzaits know as Akkalat, the White Fortress, was built by the fearsome Padishah Hoshtar on one of his periodic attempts to conquer the Devseg. For decades the sacred flame that burned from the top of the citadel symbolised his suzerainty over the tribes here. But the Padishah''s realm like the Empire is on the defensive and has retreated to the east. Today the Khan''s horsetail banners fly in its place.'),
  ('baltakhand', 'Baltakhand', 'Town', 4, 'khuzait_khanate', 'Mesui', 1800.0, 'Baltakhand, the Fortress of the Axe, was settled by the Iltanlar, mountain-dwelling cousins of the Khuzaits. Centuries ago their beys descended into the plains and created the fortress here that guards the Portages of Iltan, the network of lakes and rivers that divides the 6n lands from the Khuzaits''s realm. Bitter winters protected them from the reach of the Empire, but no blast of wind was cutting enough to stop the horsemen of Khan Urkhun, who 40 years ago forced this town to submit to the khanate.'),
  ('chaikand', 'Chaikand', 'Town', 4, 'khuzait_khanate', 'Monchug', 3900.0, 'Chaikand is a town of the Khuzaits owned by Monchug Khan of the Urkhunait. The villages of Okhutan, Ispantar, and Pabastan are bound to the town.'),
  ('makeb', 'Makeb', 'Town', 4, 'khuzait_khanate', 'Monchug', 3700.0, 'Makeb is a town of the Khuzaits owned by Monchug Khan of the Urkhunait. The villages of Shapeshte, Hanekhy, and Mazen are bound to the town.'),
  ('odokh', 'Odokh', 'Town', 4, 'khuzait_khanate', 'Akrum', 1700.0, 'The town of Odokh sits at the foot of Kohi Rohini, the mountains of the dawn. Among the most remote of the towns of the Devseg, it is reputed to have been the abode of King Ahhak, a mythical tyrant from whose shoulders flowed serpents. Even today the Kohi Rohini has a reputation for black magic and mystery that helps keep outsiders at bay. The city fell during the Khuzaits conquest to the Harfit clan, who have intermarried with the mountain peoples, and who honor their customs, participate in their rituals, and keep their secrets.'),
  ('ortongard', 'Ortongard', 'Town', 4, 'khuzait_khanate', 'Tulag', 3200.0, 'Ortongard sits in the dry center of the Devseg plateau, which is dry for most of the year but offers rich grazing in the spring. Founded by Darshi-speaking merchants, it made its wealth buying horses, sheep and cattle from the surrounding herding villages and sending them west to the markets of the Empire in huge drives, accompanied by guards to ward off raiders from the steppes. Neither its walls nor its mercenary armies could withstand the coming of Khan Urkhun, however, who it granted to the Khergit clan in recognition of their valor.'),
  ('balgard', 'Balgard', 'Town', 6, 'sturgia', 'Raganvad', 2300.0, 'Balgard, which sits on the icy waters of Mazopor Bay, was founded by migrants from the Nordlands. Legend holds that the initial wave of Nords arrogantly demanded tribute from the nearby Vakken and 6n tribes, who formed an alliance and drove the newcomers back to their ships. But the victors fell out over the spoils, until a canny Nord, Gundar, landed and volunteered to help them fairly divvy up the weapons and armor of his dead kinsmen. The residents recognized Gundar''s lordship over the region and his descendants, intermarried with the 6ns, are today the grand princes of Sturgian.[1]'),
  ('omor', 'Omor', 'Town', 6, 'sturgia', 'Olek', 3200.0, 'Omor sits on the eastern shores of Lake Laconis. Long before the 6ns formed themselves into a principality it was a holy site for the forest tribes, who worshipped their gods and ancestors in the sacred oak trees of the nearby woods. Today, it is an emporium for fur trappers and woodsmen who prowl the Ircara Wildlands to the east, and the primeval peace of the forests is drowned out by the sounds of bartering, saws, and the unloading of ships at the lake.[1]'),
  ('revyl', 'Revyl', 'Town', 6, 'sturgia', 'Vyldur', 3100.0, 'Revyl, chief town of the rocky Kachyar Peninsula, was a traditional rival of Balgard. According to legend the Balgardian princess Arkina, whose husband had been slain by the Revylians, accepted a proposal from her enemy''s king to marry and settle the feud. On her wedding night, however, she barred the door of his hall and burned him and a hundred of his kinsmen and warriors alive inside. The feud has long since been settled by pacts and marriages with happier outcomes, although Revylians still resent the ascent of the Balgardian Gundaroving dynasty.[1]'),
  ('sibir', 'Sibir', 'Town', 6, 'sturgia', 'Fafen', 1900.0, 'Sibir was founded in a dark valley amid the Chertyg Mountains by Nordic traders, who wished a base to buy furs from the local Vakken-speaking foresters. As the 6n tribes became principalities, and elected chieftains evolved into boyars who demanded taxes and labor as their due, this region became a magnet for 6ns who had little taste for deference. Today, the ambitious Isyaroving family governs this region, but they must always balance their hunger for wealth and men to fight their wars with their subjects'' reluctance to provide it.[1]'),
  ('tyal', 'Tyal', 'Town', 6, 'sturgia', 'Godun', 1700.0, 'Tyal sits in the western foothills of Mount Iltan, on the eastern borders of the 6n lands. This region has long stood aloof from the power struggles of the other 6n principalities. Its people are known as wanderers, traders, horse breeders and fur-trappers. The local aristocracy has occasionally exchanged princesses with the steppe tribes to the east to firm up a truce or a trade pact, and proudly includes the names of several great khans on their list of ancestors.[1]'),
  ('varcheg', 'Varcheg', 'Town', 6, 'sturgia', NULL, 3100.0, 'The former Nord colony of Varcheg sits on a windswept sea-bluff at the base of the Kachyar peninsula, in what was once 2n land. The jarl who founded this coastal outpost, hoping to trade with the interior, pledged himself in fealty to the 2n High King Dernmachad, but then proceeded to dabble in 2n politics. Annoyed, Dernmachad hired a 6n army to crush his unreliable new vassal. The 6ns complied and routed the Nords, but then demanded the newly captured town as their payment. They called the town ''Varcheg'', a corruption of the Nordic term for ''oathsworn companion'', to mock both rivals whose quarreling had handed them their prize.'),
  ('varnovapol', 'Varnovapol', 'Town', 6, 'sturgia', 'Yorig', 3300.0, 'Varnovopol, which sits beneath the Chertyg Mountains on the crystal waters of Lake Laconis, has the dubious honor of being perhaps the most-often conquered city in Calradia. Originally it was a colony of the Empire, infamous as a place of exile for dissident senators, before it was seized by Nords as a base to expand their influence into the 6n fur trade. It was taken by the Alkit tribe from the eastern steppe and briefly served as the capital of a small khanate, before finally falling to the fierce Ormidoving clan.[1]'),
  ('charas', 'Charas', 'Town', 7, 'vlandia', 'Ingalther', 3000.0, 'The city known today as Charas is traditionally reckoned to be the first Calradian colony on the shores of their new continent. At the Empire''s height, when the capital moved north to Paravenos, Charasea remained a key hub of sea-faring and trade, while imperial aristocrats built their summer homes on the warm shores of the nearby gulf and cruised their pleasure-boats around its islands. When the 7ns came, Charas fell into the hands of the ruthless House of dey Cortain, and its wealth funds their ambitions.'),
  ('galend', 'Galend', 'Town', 7, 'vlandia', 'Derthert', 1900.0, 'Galend overlooks the wave-beaten Biscan coast. It takes in the catch from the Biscan''s intrepid fishermen who venture out far into the western ocean, as well as the wool of sheep from the green fog-covered hills. The current line of 7n kings comes from the clans who settled in this region during Osric Iron-Arm''s invasion.'),
  ('jaculan', 'Jaculan', 'Town', 7, 'vlandia', 'Calatild', 4000.0, 'Jaculan sits in the warmer southern reaches of the Biscan coast, in rolling hills known for their olive trees. It was once a favored resort of the imperial aristocracy, who hunted wild boars amid the oak forests. The independent peasantry of this region are known for their heterodox ideas. The Brotherhood of the Woods is but the latest of a series of rebellions to have broken out here, sometimes aided by an aristocracy that considers them a tool to use against rival 7n houses.'),
  ('ocs_hall', 'Ocs Hall', 'Town', 7, 'vlandia', 'Belgir', 4200.0, 'Ocs Hall is one of the few towns in the Vlandian kingdom that was founded after the seizure of the land from the Empire. This valley was once an isolated holdout of 2ns, centered on the Llyn Modris, a lake in a volcanic caldera that was said to be the  seat of a giant. This land was conquered by the 7n warlord Oca, who also gave his name to the nearby Ocspool lake. The 2n tribes were driven inland, and took their legends with them.'),
  ('ostican', 'Ostican', 'Town', 7, 'vlandia', 'Hecard', 3900.0, 'Ostican was a minor imperial port that became a haven for seafarers of the northern oceans. Many were talented corsairs, employed by imperial factions to harry their foes during the latter empire''s intermittent civil wars. Indeed, the some of the first 7ns to come to Calradia''s shores settled in the back alleys of this town, and no doubt sent word to their kinsmen of the riches to be had here should anyone invade in earnest.'),
  ('pravend', 'Pravend', 'Town', 7, 'vlandia', 'Aldric', 3200.0, 'The city, formerly known as Paravenos, was the second major colony founded by Calradios the Great and the Calradians after their arrival on the continent. The town succeeded Charasea as the capital of the Calradic Empire, being so for centuries before the center of gravity of the Empire moved eastward. Nevertheless, Paravenos retained its primacy as the economic center of the West. When Osric Iron-Arm invaded, he recognized Paravenos would be far more valuable as a seat of power than as simply as a source of loot, and negotiated its surrender with local senators. The city subsequently passed under the control of the dey Tihr, a cadet branch of the ruling clan of Vlandian, the dey Meroc.'),
  ('rovalt', 'Rovalt', 'Town', 7, 'vlandia', 'Servic', 2800.0, 'Rovalatys, in the mountains of the Ebor peninsula, was never fully an imperial town. Nordic migrants, drawn to the region by rumors of riches to be made prospecting for silver or hunting for furs, long outnumbered Calradians even before the 7n invasion. The 7ns too recognized its potential, and despite its harsh winters this land is among the more populous regions of the kingdom, with bountiful fields in the valleys of the mountains feeding the constant flow of settlers from the south drawn here by their hunger for wealth.'),
  ('sargot', 'Sargot', 'Town', 7, 'vlandia', 'Derthert', 4500.0, 'Sargot is a town in Vlandian owned by King Derthert of House dey Meroc.'),
  ('amprela', 'Amprela', 'Town', 3,'northern_empire', 'Encurion', 2300.0, 'Amprela is a town in the Northern Empire owned by Archon Encurion of clan Impestores. The villages of Avasinton and Boreagora are bound to the town.'),
  ('argoron', 'Argoron', 'Town', 3, 'northern_empire', 'Lucon', 2800.0, 'The city of Argoron sits where the cold, slow moving Nevys River meets Lake Laconis. This was once the land of the Laconians, who saw the Empire as a protector against the more warlike Palaic peoples. They welcomed and intermarried with imperial settlers and their chiefs joined the Senate, and their old language and customs faded away.[1]'),
  ('diathma', 'Diathma', 'Town', 3, 'northern_empire', 'Lucon', 4700.0, 'Diathma, the city of the Divine Decree, was erected by an imperial general on the ruins of a Dryatic shrine overlooking Lake Laconis. It was the last stand of the Dryatics, the northernmost of the Palaic peoples, who rebelled against the Empire and were overcome. According to legend they were pushed back into the shallows of the lake and fought until they were exhausted and the bloody waters engulfed them.[1]'),
  ('epicrotea', 'Epicrotea', 'Town', 3, 'northern_empire', 'Manteos', 5100.0, 'Epicrotea, the ''All-Conquering,'' was named after the eccentric long-haired military genius Sarapios, who crushed a 2n host and secured the lands west of Lake Laconis for the Empire. Its towers, overlooking the Miron River, have frequently been a northerner''s first glimpse of the awesome and terrible force to their south.[1]'),
  ('myzea', 'Myzea', 'Town', 3, 'northern_empire', 'Gyphor', 3900.0, 'Myzea is a town of the Northern Calradic Empire owned by the archon Gyphor of the Dolentos clan.'),
  ('saneopa', 'Saneopa', 'Town', 3, 'northern_empire', 'Penton', 4600.0, 'Saneopa is a town of the Kingdom of Northern Empire owned by the archon Penton of the Neretzes clan.'),
  ('ain_baliq_castle', 'Ain Baliq Castle', 'Castle', 1, 'aserai', 'Awdhan', 980.0, 'Ain Baliq Castle is a castle of the Aserai owned by Emir Awdhan of the Banu Sarmal. The villages of Ain Baliq and Deir Hawa are bound to the castle.'),
  ('barihal_castle', 'Barihal Castle', 'Castle', 1, 'aserai', 'Aqar', 610.0, 'Barihal Castle is a castle of the Aserai owned by Emir Aqar of the Banu Ruwaid. The villages of Barihal and Wadar are bound to the castle.'),
  ('jamayeh_castle', 'Jamayeh Castle', 'Castle', 1, 'aserai', 'Suruq', 610.0, 'Jamayeh Castle is a castle of the Aserai Sultanate ruled by emir Suruq of the Banu Qaraz clan. The villages of Jamayeh and Hunab are bound to the castle.'),
  ('medeni_castle', 'Medeni Castle', 'Castle', 1, 'aserai', 'Adram', 750.0, 'Medeni Castle is a castle in the Aserai Sultanate ruled by the emir Adram of the Banu Sarran. The villages of Medeni and Qidnar are bound to the castle.'),
  ('sahel_castle', 'Sahel Castle', 'Castle', 1, 'aserai', 'Tais', 890.0, 'Sahel Castle is a castle of the Aserai owned by Emir Tais of the Banu Qild. The villages of Sahel and Asmait are bound to the castle.'),
  ('shibal_zumr_castle', 'Shibal Zumr Castle', 'Castle', 1, 'aserai', 'Tais', 570.0, 'Shibal Zumr Castle is a castle of the Aserai owned by Emir Tais of the Banu Qild. The villages of Shibal Zumr and Lamesa are bound to the castle.'),
  ('tamnuh_castle', 'Tamnuh Castle', 'Castle', 1, 'aserai', 'Hashan', 590.0, 'Tamnuh Castle is a castle of the Aserai owned by Emir Hashan of the Banu Habbab. The villages of Tamnuh and Kuqa are bound to the castle.'),
  ('tubilis_castle', 'Tubilis Castle', 'Castle', 1, 'aserai', 'Unqid', 460.0, 'Tubilis Castle is a castle of the Aserai Sultanate owned by Sultan Unqid.  The villages of Tubilis and Fanab are bound to the castle.'),
  ('uqba_castle', 'Uqba Castle', 'Castle', 1, 'aserai', 'Awdhan', 550.0, 'Uqba Castle is a castle of the Aserai owned by Emir Awdhan of the Banu Sarmal. The villages of Uqba and Bunqaz are bound to the castle.'),
  ('ab_comer_castle', 'Ab Comer Castle', 'Castle', 2, 'battania', 'Maireas', 880.0, 'Ab Comer Castle is a castle in Battanian owned by Mormaer Maireas of clan fen Caernacht. The vilages of Ab Comer and Inveth are bound to the castle.'),
  ('aster_castle', 'Aster Castle', 'Castle', 2, 'battania', 'Ergeon', 652.0, 'Aster Castle is a castle within the lands of Battanian owned by the chieftain Ergeon of Clan fen Derngil.'),
  ('druimmor_castle', 'Druimmor Castle', 'Castle', 2, 'battania', 'Aradwyr', 1060.0, 'Druimmor Castle is a castle of Battanian owned by the chieftain Aradwyr of the Clan fen Eingal.'),
  ('flintolg_castle', 'Flintolg Castle', 'Castle', 2, 'battania', 'Luichan', 720.0, 'Flintolg Castle is a castle within the lands of Battanian owned by the chieftain Luichan of Clan fen Penraic.'),
  ('llanoc_hen_castle', 'Llanoc Hen Castle', 'Castle', 2, 'battania', 'Pryndor', 720.0, 'Llanoc Hen Castle is a castle in Battanian owned by Mormaer Pryndor of clan fen Morcar. The villages of Llanoc Hen and Cantrec are bound to the castle.'),
  ('pendraic_castle', 'Pendraic Castle', 'Castle', 2, 'battania', NULL, 950.0, 'Pendraic Castle is a castle in Battanian owned by the mormaer, Melidir of Clan fen Uvain. The villages of Pendraic and Lindorn are bound to the castle.'),
  ('rhemtoil_castle', 'Rhemtoil Castle', 'Castle', 2, 'battania', 'Caladog', 860.0, 'Rhemtoil Castle is a castle in Battanian owned by High King Caladog of clan fen Gruffendoc. The villages of Rhemtoil and Claig Ban are bound to the castle.'),
  ('uthelaim_castle', 'Uthelaim Castle', 'Castle', 2, 'battania', 'Caladog', 960.0, 'Uthelaim Castle is a castle in Battanian owned by High King Caladog of clan fen Gruffendoc. The villages of Uthelaim and Seordas are bound to the castle.'),
  ('akiser_castle', 'Akiser Castle', 'Castle', 4, 'khuzait_khanate', 'Hurunag', 480.0, 'Akiser Castle is a castle of the Khuzaits owned by Hurunag Beg of the Tigrit. The villages of Akiser and Kamshar are bound to the town.'),
  ('dinar_castle', 'Dinar Castle', 'Castle', 4, 'khuzait_khanate', 'Ilatar', 620.0, 'Dinar Castle is a castle of the Khuzaits owned by Ilatar Beg of the Baltait. The villages of Dinar and Karahalli are bound to the castle.'),
  ('erzenur_castle', 'Erzenur Castle', 'Castle', 4, 'khuzait_khanate', 'Gusukan', 430.0, 'Erzenur Castle is a castle of the Khuzaits owned by Gusukan Beg of the Oburit. The villages of Erzenur and Gereden are bound to the castle.'),
  ('hakkun_castle', 'Hakkun Castle', 'Castle', 4, 'khuzait_khanate', 'Taslur', 660.0, 'Hakkun Castle is a castle of the Khuzaits owned by Taslur Beg of the Yanserit. The villages of Hakkun and Kiraz are bound to the castle.'),
  ('kaysar_castle', 'Kaysar Castle', 'Castle', 4, 'khuzait_khanate', 'Ilatar', 520.0, 'Kaysar Castle is a castle of the Khuzaits owned by Ilatar Beg of the Baltait. The villages of Kaysar and Payam are bound to the castle.'),
  ('khimli_castle', 'Khimli Castle', 'Castle', 4, 'khuzait_khanate', 'Kanujan', 520.0, 'Khimli Castle is a castle of the Khuzaits owned by Kanujan Beg of the Koltit. The villages of Khimli and Omrotok are bound to the castle.'),
  ('simira_castle', 'Simira Castle', 'Castle', 4, 'khuzait_khanate', 'Kanujan', 420.0, 'Simira Castle is a castle of the Khuzaits owned by Kanujan Beg of the Koltit. The villages of Simira and Kohi Ajik are bound to the castle.'),
  ('tepes_castle', 'Tepes Castle', 'Castle', 4, 'khuzait_khanate', 'Monchug', 530.0, 'Tepes Castle is a castle of the Khuzaits owned by Monchug Khan of the Urkhunait. The villages of Tepes and Kuruluk are bound to the town.'),
  ('usek_castle', 'Usek Castle', 'Castle', 4, 'khuzait_khanate', 'Tulag', 420.0, 'Usek Castle is a castle of the Khuzaits owned by Tulag Beg of the Arkit. The villages of Usek and Esme are bound to the castle.'),
  ('mazhadan_castle', 'Mazhadan Castle', 'Castle', 6, 'sturgia', 'Raganvad', 830.0, 'Mazhadan Castle is a castle in Sturgian owned by Grand Prince Raganvad of clan Gundaroving. The villages of Forin and Mazhadan are bound to the castle.'),
  ('kranirog_castle', 'Kranirog Castle', 'Castle', 6, 'sturgia', 'Rolan', 1000.0, 'Kranirog Castle is a castle of Sturgian owned by Rolan of the Kostoroving clan. The castle''s bound villages are Kranirog and Ismilkorg.'),
  ('nevyansk_castle', 'Nevyansk Castle', 'Castle', 6, 'sturgia', 'Raganvad', 470.0, 'The castle watches over a contentious piece of territory separated from Sturgian proper. Reinforcements must pass through rugged 2n countryside to reach the castle.'),
  ('ov_castle', 'Ov Castle', 'Castle', 6, 'sturgia', 'Vashorki', 800.0, 'Ov Castle is a castle in Sturgian owned by Vashorki of clan Vezhoving. It overlooks the land bridge which is the only passage from the western half of Sturgian to the eastern half.'),
  ('takor_castle', 'Takor Castle', 'Castle', 6, 'sturgia', 'Tovir', 680.0, 'Takor Castle is a castle in Sturgian owned by Knyaz Tovir of clan Ubroving. The villages of Takor and Dvorusta are bound to the castle.'),
  ('urikskala_castle', 'Urikskala Castle', 'Castle', 6, 'sturgia', 'Godun', 660.0, 'Urikskala Castle is a castle in Sturgian owned by Knyaz Godun of clan Vagiroving. The villages of Urikskala and Alov are bound to the castle.'),
  ('ustokol_castle', 'Ustokol Castle', 'Castle', 6, 'sturgia', 'Vyldur', 890.0, 'Ustokol Castle is a castle within the Principality of Sturgian owned by Vyldur of the Togaroving clan. The castle''s bound villages are Ustokol and Zhemyan.'),
  ('vladiv_castle', 'Vladiv Castle', 'Castle', 6, 'sturgia', 'Yorig', 990.0, 'Vladiv Castle is a castle in Sturgian owned by Knyaz Yorig of clan Ormidoving. The villages of Vladiv and Glavstrom are bound to the castle.'),
  ('caleus_castle', 'Caleus Castle', 'Castle', 7, 'vlandia', 'Servic', 760.0, 'Caleus Castle is a castle of the Kingdom of Vlandia ruled by the baron Servic of the clan dey Valant.'),
  ('drapand_castle', 'Drapand Castle', 'Castle', 7, 'vlandia', 'Aldric', 830.0, 'Drapand Castle is a castle in Vlandian owned by Baron Aldric of House dey Tihr. The villages of Drapand and Valanby are bound to the castle.'),
  ('hongard_castle', 'Hongard Castle', 'Castle', 7, 'vlandia', 'Vartin', 1020.0, 'Hongard Castle is a castle in Vlandian owned by Baron Vartin of House dey Jelind. The villages of Hongard and Ferton are bound to the castle.'),
  ('ormanfard_castle', 'Ormanfard Castle', 'Castle', 7, 'vlandia', NULL, 650.0, 'Ormanfard Castle is a castle in Vlandian owned by the baron, Ecarand of House dey Folcun. It guards one of several mountain passes which leads from Battanian into Vlandian.'),
  ('talivel_castle', 'Talivel Castle', 'Castle', 7, 'vlandia', 'Derthert', 770.0, 'Talivel Castle is a castle in Vlandian owned by King Derthert of House dey Meroc. The castle serves as a frontier stronghold for the 7ns, guarding one of the key mountain passes leading into Battanian, and is thus at risk of being attacked first should it come to war.'),
  ('tirby_castle', 'Tirby Castle', 'Castle', 7, 'vlandia', NULL, 630.0, 'Tirby Castle is a castle in Vlandian owned by the baron, Ospir of the House dey Gunric. The villages of Tirby and Sirindac are both bound to the castle.'),
  ('usanc_castle', 'Usanc Castle', 'Castle', 7, 'vlandia', 'Berican', 537.0, 'Usanc Castle is a castle in Vlandian owned by Baron Berican of House dey Rothad. The village of Usanc is bound to the castle.'),
  ('verecsand_castle', 'Verecsand Castle', 'Castle', 7, 'vlandia', NULL, 780.0, 'Verecsand Castle is a castle in Vlandian owned by the baron, Belgir of the House dey Fortes. The villages of Verecsand and Marin are bound to the castle.'),
  ('ataconia_castle', 'Ataconia Castle', 'Castle', 3, 'northern_empire', 'Manteos', 960.0, 'Ataconia Castle is a castle of the Northern Calradic Empire owned by Manteos of the Argoros clan. The villages of Ataconia and Potamis are bound to the castle.'),
  ('atriom_castle', 'Atriom Castle', 'Castle', 3, 'northern_empire', NULL, 0.0, 'Atrion Castle       Settlement Information  Type Castle   Kingdom Northern Empire   Villages Atriom, Masangara    Atrion Castle is a castle of the Northern Calradic Empire.'),
  ('gaos_castle', 'Gaos Castle', 'Castle', 3, 'northern_empire', 'Penton', 860.0, 'Gaos Castle is a castle in the Northern Empire owned by Archon Penton of clan Neretzes. The villages of Gaos and Themys are bound to the castle.'),
  ('epinosa_castle', 'Epinosa Castle', 'Castle', 3, 'northern_empire', 'Tasynor', 990.0, 'Epinosa Castle is a castle of the Northern Calradic Empire owned by the archon Tasynor of the Phalentes clan. Along with Lochana Castle and Syratos Castle, Epinosa guards the northwestern frontier of the Empire against the bordering 6ns and 4s.'),
  ('lochana_castle', 'Lochana Castle', 'Castle', 3, 'northern_empire', 'Nicasor', 500.0, 'Lochana Castle is a castle in the Northern Empire owned by Nicasor of clan Chonis. Along with Epinosa Castle and Syratos Castle, Lochana guards the northwestern frontier of the Empire against the bordering 6ns and Khuzait.'),
  ('mecalovea_castle', 'Mecalovea Castle', 'Castle', 3, 'northern_empire', 'Lucon', 870.0, 'Mecalovea Castle is a castle in the Northern Empire owned by Emperor Lucon of clan Osticos. The castle protects strategic river crossings between Sturgian and the Calradic Empire. The villages of Agalmon and Mecalovea are bound to the castle.'),
  ('rhesos_castle', 'Rhesos Castle', 'Castle', 3, 'northern_empire', 'Porphalios', 720.0, 'Rhesos Castle is a castle in the Northern Empire owned by Archon Porphalios of clan Serapides.  The villages of Rhesos and Dyopalis are bound to the castle.'),
  ('syratos_castle', 'Syratos Castle', 'Castle', 3, 'northern_empire', 'Maritzios', 560.0, 'Syratos Castle is a castle in the Northern Empire owned by Archon Maritzios of clan Vatatzes. The villages of Syratos and Tememos are bound to the castle.'),
  ('varagos_castle', 'Varagos Castle', 'Castle', 3, 'northern_empire', 'Penton', 420.0, 'Varagos Castle is a castle of the Northern Calradic Empire owned by the archon Penton of the Neretzes clan.'),
  ('chanopsis_castle', 'Chanopsis Castle', 'Castle', 3, 'southern_empire', 'Rhagaea', 480.0, 'Chanopsis Castle is a castle in the Southern Empire owned by Empress Rhagaea of clan Pethros.'),
  ('corenia_castle', 'Corenia Castle', 'Castle', 3, 'southern_empire', 'Baranor', 770.0, 'Corenia Castle is a castle in the Southern Empire owned by Archon Baranor of clan Julios. The villages of Corenia and Metachia are bound to the castle.'),
  ('jogurys_castle', 'Jogurys Castle', 'Castle', 3, 'southern_empire', 'Satros', 1050.0, 'Jogurys Castle is a castle in the Southern Empire owned by Archon Satros of clan Vetranis. The villages of Jogurys and Eunalica are bound to the castle.'),
  ('lavenia_castle', 'Lavenia Castle', 'Castle', 3, 'southern_empire', 'Oros', 1100.0, 'Lavenia Castle is a castle in the Southern Calradic Empire owned by Oros of the Mestricaros clan.'),
  ('melion_castle', 'Melion Castle', 'Castle', 3, 'southern_empire', 'Serandon', 810.0, 'Melion Castle is a castle in the Southern Calradic Empire owned by the archon Serandon of the Avlonos clan.'),
  ('morenia_castle', 'Morenia Castle', 'Castle', 3, 'southern_empire', 'Abalytos', 850.0, 'Morenia Castle is a castle in the Southern Calradic Empire owned by the archon Abalytos of the Prienicos clan.'),
  ('odrysa_castle', 'Odrysa Castle', 'Castle', 3, 'southern_empire', 'Oros', 500.0, 'Odrysa Castle is a castle in the Southern Empire owned by Archon Oros of clan Mestricaros. The villages of Odrysa and Caira are bound to the castle.'),
  ('sestadaim_castle', 'Sestadaim Castle', 'Castle', 3, 'southern_empire', 'Rhagaea', 670.0, 'Sestadaim Castle is a castle in the Southern Empire owned by Empress Rhagaea of clan Pethros. The villages of Amycon and Sestadaim are bound to the castle.'),
  ('garontor_castle', 'Garontor Castle', 'Castle', 3, 'western_empire', 'Apys', 880.0, 'Garontor Castle is a castle of Western Empire owned by Apys of the Varros clan. Both the villages of Garontor and Lysia are bound to the castle.'),
  ('gersegos_castle', 'Gersegos Castle', 'Castle', 3, 'western_empire', 'Saratis', 610.0, 'Gersegos Castle is a castle in the Western Empire owned by Archon Saratis of clan Sorados. The villages of Gersegos and Vathea are bound to the castle.'),
  ('hertogea_castle', 'Hertogea Castle', 'Castle', 3, 'western_empire', 'Vipon', 640.0, 'Hertogea Castle is a castle of Western Empire owned by by Vipon of the Maneolis clan. The villages of Hertogea and Nideon are bound to the castle.'),
  ('onica_castle', 'Onica Castle', 'Castle', 3, 'western_empire', 'Garios', 740.0, 'Onica Castle is a castle in the Western Empire owned by Emperor Garios of clan Comnos. The villages of Onica and Tarcutis are bound to the castle.'),
  ('oristocorys_castle', 'Oristocorys Castle', 'Castle', 3, 'western_empire', 'Vincantios', 820.0, 'Oristocorys Castle is a castle in the Western Empire owned by Archon Vincantios of clan Palladios. The villages of Oristocorys and Elvania are bound to the castle.'),
  ('thorios_castle', 'Thorios Castle', 'Castle', 3, 'western_empire', 'Tynops', 760.0, 'Thorios Castle is a castle in the Western Empire owned by Archon Tynops of clan Elaches. The villages of Thorios and Bergum are bound to the castle.'),
  ('thractorae_castle', 'Thractorae Castle', 'Castle', 3, 'western_empire', 'Crotor', 660.0, 'Thractorae Castle is a castle of Western Empire owned by by Crotor of the Dionicos clan. The villages bound to the castle are Thractorae and Gamardan.'),
  ('veron_castle', 'Veron Castle', 'Castle', 3, 'western_empire', NULL, 610.0, 'Veron Castle is a castle of Western Empire initially owned by clan Corenios at the start of the game.');
INSERT INTO villages (village_id, name, culture_id, settlement_id, primary_resource, hearth, description) VALUES
  ('kafr_hatif', 'Kafr Hatif', 1, 'askar', 'Desert Horses', 0.0, 'Kafr Hatif is a village in the Aserai Sultanate ruled by the emir Iyalas of the Banu Arbas. The village is bound to Askar and is known to produce Desert Horses.'),
  ('mabwaz', 'Mabwaz', 1, 'askar', 'Grain', 235.0, 'Mabwaz is a village in the Aserai Sultanate ruled by the emir Iyalas of the Banu Arbas. The village is bound to Askar and is known to produce Grain.'),
  ('zalm', 'Zalm', 1, 'askar', 'Grain', 258.0, 'Zalm is a village in the Aserai Sultanate ruled by the emir Iyalas of the Banu Arbas. The village is bound to Askar and is known to produce Grain.'),
  ('mahloul', 'Mahloul', 1, 'hubyar', 'Desert Horses', 231.0, 'Mahloul sits in a broad valley between the Jarjara Escarpment and the Jabal Ashabi Mountains in the desert steppe southeast of the Bahr al-Yeshm. Groundwater provides just enough water to grow crops for subsistence, while the village makes its money from rearing horses on the rich grass that grows in the Jabal Ashabi after the spring rains.[1]'),
  ('liwas', 'Liwas', 1, 'hubyar', 'Desert Horses', 150.0, 'Liwas sits in a broad valley south of the Bahr al-Yeshm. Farmland is limited here, and the land is best known for the horses that are grazed on the desert''s short-lived but rich spring grasses.[1]'),
  ('waltas', 'Waltas', 1, 'hubyar', 'Flax', 155.0, 'Waltas sits by the Bahr al-Yeshm, the Jade Sea, in lowlands well suited to the growing of flax.[1]'),
  ('abu_khih', 'Abu Khih', 1, 'husn_fulq', 'Dates', 297.0, 'Abu Khih sits along the Nahr al-Kals River on its way to its barren southern reaches. The surrounding lands, an ancient lakebed, are already becoming barren and alkaline, although date-palms still thrive.[1]'),
  ('hoqqa', 'Hoqqa', 1, 'husn_fulq', 'Horses', 243.0, 'Hoqqa sits on the far east of the Aserai lands, on the Tyagis River. The land is mostly desert-steppe. Barren most of the year except for scrub, it is covered in grass and flowers in the spring and is fine grazing for horses.[1]'),
  ('abba', 'Abba', 1, 'iyakis', 'Grain', 282.0, 'Abba sits on the edge of the deep desert, at the foot of the landward side of the Jarjara Escarpment. Runoff from the hills is trapped underground here, creating springs that sustain an oasis. Wheat thrives in the fields and gardens.[1]'),
  ('bir_seif', 'Bir Seif', 1, 'iyakis', 'Clay', 131.0, 'Bir Seif is centered around a group of wells and pools in the Jarjara Escarpment. Villagers dig down to the shallow groundwater layer for clay to sell to the potters of the Nahasa Desert. [1]'),
  ('ezbet_nahul', 'Ezbet Nahul', 1, 'qasira', 'Grain', 326.0, 'Ezbet Nahul is a village in the Aserai Sultanate ruled by the emir Talas of the Banu Atij. The village is bound to Qasira and is known to produce Grain.'),
  ('abghan', 'Abghan', 1, 'qasira', 'Fish', 233.0, 'Abghan is a village in the Aserai Sultanate ruled by the emir Talas of the Banu Atij. The village is bound to Qasira and is known to produce Fish.'),
  ('tasheba', 'Tasheba', 1, 'quyaz', 'Fish', 300.0, 'Tasheba lies on the western edges of the Bahr al-Yeshm. Fishermen venture out into the protected waters, gentle and calm for most of the year, for tuna and sardines.[1]'),
  ('baq', 'Baq', 1, 'quyaz', 'Olives', 235.0, 'Baq slightly inland from the Bahr al-Yeshm sea, beneath the great granite outcrop of the Jabal Tamar Mountains. The seawinds bring the uplands here just enough rain to support the cultivation of olive trees.[1]'),
  ('hiblet', 'Hiblet', 1, 'quyaz', 'Dates', 183.0, 'Hiblet sits at the base of the granite outcrop known as the Jabal Tamar Mountains. Rainwater trapped in cracks in the rock is diverted to the village''s date-palm gardens.[1]'),
  ('mussum', 'Mussum', 1, 'razih', 'Dates', 454.0, 'Mussum sits near the eastern coast of the Bahr al-Yeshm sea, where the Aserai deserts give way to desert-steppe with scattered acacia and scrub. The villagers here sink wells to water their groves of date palms.[1]'),
  ('qablab', 'Qablab', 1, 'razih', 'Salt', 502.0, 'Qablab sits near a broad bay on the southern coast of the Perassic Sea. The low-lying coastline is well-suited to the construction of salt pans.[1]'),
  ('doqa', 'Doqa', 1, 'razih', 'Fish', 454.0, 'Doqa is a fishing village on the Bahr al-Yeshm sea. Villagers sail out in feluccas to harvest perch that sometimes grow as long as a man is tall, keeping an eye out for the salt-water crocodiles which live in the local inlets and marshes and which compete with them for their catch.[1]'),
  ('mijayit', 'Mijayit', 1, 'sanala', 'Grain', 330.0, 'Mijayit lies off of the estuary of the Damar River as it reaches the Bahr al-Yeshm sea. The rich silt deposits left by the river make this one of the most fertile regions of the Aserai lands. [1]'),
  ('hamoshawat', 'Hamoshawat', 1, 'sanala', 'Grain', 210.0, 'Hamoshawat lies on the lower Damar River, just before it reaches the Bahr al-Yeshm sea. The rich silt deposits left by the river make this one of the most fertile regions of the Aserai lands. [1]'),
  ('jahasim', 'Jahasim', 1, 'sanala', 'Fish', 610.0, 'Jahasim sits on the southern shore of the sea that the Aserai call the Bahr al-Yeshm. The warm waters abound in tuna, bonito, sardines, and other fish. [1]'),
  ('nahlan', 'Nahlan', 1, 'sanala', 'Grain', 220.0, 'Nahlan sits on the floodplain of the Damar River as it cuts through the Jarjara Escarpment. This soil, refreshed yearly by the silt of the flooding river, produces bountiful crops of wheat. [1]'),
  ('geunat_nal', 'Geunat Nal', 2, 'car_banseth', 'Furs', 250.0, 'Geunat Nal is a village in Battanian owned by the chieftain Melidir of Clan fen Uvain. The village is bound to Car Banseth and known to produce Furs.'),
  ('tor_leiad', 'Tor Leiad', 2, 'car_banseth', 'Hardwood', 147.0, 'Tor Leiad is a village in Battanian owned by the chieftain Melidir of Clan fen Uvain. The village is bound to Car Banseth and known to produce Hardwood.'),
  ('bog_beth', 'Bog Beth', 2, 'car_banseth', 'Furs', 550.0, 'Bog Beth is a village in Battanian owned by the chieftain Melidir of Clan fen Uvain. The village is bound to Car Banseth and known to produce Furs.'),
  ('diantogmail', 'Diantogmail', 2, 'dunglanys', 'Grapes', 275.0, 'Diantogmail is a village of Battanian owned by the chieftain Ergeon of the Clan fen Derngil. The village is bound to Dunglanys and known to produce Grapes.'),
  ('glenlithrig', 'Glenlithrig', 2, 'dunglanys', 'Hardwood', 529.0, 'Glenlithrig is a village of Battanian owned by the chieftain Ergeon of the Clan fen Derngil. The village is bound to Dunglanys and known to produce Hardwood.'),
  ('morihig', 'Morihig', 2, 'dunglanys', 'Hogs', 442.0, 'Morihig is a village of Battanian owned by the chieftain Ergeon of the Clan fen Derngil. The village is bound to Dunglanys and known to produce Hogs.'),
  ('ath_cafal', 'Ath Cafal', 2, 'marunath', 'Clay', 374.0, 'Ath Cafal is a village in Battanian owned by High King Caladog of clan fen Gruffendoc. The village is bound to Marunath and is known to produce Clay.'),
  ('beglomuar', 'Beglomuar', 2, 'marunath', 'Iron Ore', 480.0, 'Beglomuar is a village in Battanian owned by High King Caladog of clan fen Gruffendoc. The village is bound to Marunath and known to produce Iron Ore.'),
  ('dalmengus', 'Dalmengus', 2, 'marunath', 'Grain', 131.0, 'Dalmengus sits by the side of the Llyn Tywal, the Dark Lake at the center of the Uchalion massif. The flat, well-watered lands here are fertile and well-suited to wheat and barley.[1]'),
  ('ebereth', 'Ebereth', 2, 'marunath', 'Hardwood', 490.0, 'Ebereth is a village in Battanian owned by High King Caladog of clan fen Gruffendoc. The village is bound to Marunath and known to produce Hardwood.'),
  ('durn', 'Durn', 2, 'pen_cannoc', 'Clay', 530.0, 'Durn is a village in Battanian owned by the chieftain Aeron of Clan fen Giall. The village is bound to Pen Cannoc and known to produce Clay.'),
  ('fenon_etir', 'Fenon Etir', 2, 'pen_cannoc', 'Grapes', 468.0, 'Fenon Etir is a village in Battanian owned by Mormaer Aeron of clan fen Giall. The village is bound to Pen Cannoc and known to produce Grapes.'),
  ('gainseth', 'Gainseth', 2, 'pen_cannoc', 'Clay', 473.0, 'Gainseth is a village in Battanian owned by the chieftain Aeron of Clan fen Giall. The village is bound to Pen Cannoc and known to produce Clay.'),
  ('andurn', 'Andurn', 2, 'seonon', 'Hardwood', 145.0, 'Andurn is a village in Battanian owned by the chieftain Luichan of the Clan fen Penraic. The village is bound to Seonon and known to produce Hardwood.'),
  ('bryn_glas', 'Bryn Glas', 2, 'seonon', 'Iron Ore', 603.0, 'Bryn Glas is a village in Battanian owned by the chieftain Luichan of Clan fen Penraic. The village is bound to Seonon and known to produce Iron Ore.'),
  ('mag_arba', 'Mag Arba', 2, 'seonon', 'Clay', 328.0, 'Mag Arba is a village in Battanian owned by Mormaer Luichan of clan fen Penraic. The village is bound to Seonon and known to produce Clay.'),
  ('swenryn', 'Swenryn', 2, 'seonon', 'Horses', 389.0, 'Swenryn is a village in Battanian owned by the chieftain Luichan of Clan fen Penraic. The village is bound to Seonon and known to produce Horses, specifically 2n Ponies.'),
  ('karakalat', 'Karakalat', 4, 'akkalat', 'Horses', 216.0, 'Karakalat lies in a basin in the flat, eastern edges of the Devseg plateau. Until recently, this land was dominated by nomads, and it is still famous as a breeding ground for horses.'),
  ('tismil', 'Tismil', 4, 'akkalat', 'Sheep', 162.0, 'Tismil sits on the Ozu river, which drains the southern end of the Devseg plateau. The people of this land are sheep-herders, who have thrived under Khuzait overlordship as the khans keep nomadic raiders at bay.[1]'),
  ('fisnar', 'Fisnar', 4, 'baltakhand', 'Sheep', 152.0, 'Fisnar sits alongside the Zakhan, a tributary of the Karakaz river. Though this valley is snowbound for much of the year, the spring grasses nonetheless sustain sizeable herds of sheep, the thick wool of which protects them from this land''s icy winds.'),
  ('ulaan', 'Ulaan', 4, 'baltakhand', 'Flax', 224.0, 'Ulaan sits in the valley of the Karakaz river. The villagers, nomads who have recently been forced by the khans to settle, have learned to grow flax in this low-lying marshy land.'),
  ('asalig', 'Asalig', 4, 'baltakhand', 'Horses', 321.0, 'Asalig sits at the foot of Bars Dag, one of the peaks that marks the edge of the Devseg plateau. Villagers raise horses in the lower slopes, keeping watch for the snow leopards for which the peak is named.[1]'),
  ('okhutan', 'Okhutan', 4, 'chaikand', 'Wheat', 326.0, 'Okhutan is a village at the center of a wheat-growing district on a narrow stretch of plain between the Akkan hills and Lake Tanaesis, which the Khuzaits call the Tanaz Sea.'),
  ('ispantar', 'Ispantar', 4, 'chaikand', 'Sheep', 327.0, 'Ispantar is a village on a rocky spur of the Akkan hills overlooking Lake Tanaesis, which the Khuzaits call the Tanaz Sea. The villagers here make most of their income from the raising of sheep.'),
  ('pabastan', 'Pabastan', 4, 'chaikand', 'Wheat', 239.0, 'Pabastan sits in the narrow plain between the Akkan hills and Lake Tanaesis, which the Khuzaits call the Tanaz Sea. This land is fine country for wheat.'),
  ('shapeshte', 'Shapeshte', 4, 'makeb', NULL, 212.0, 'Shapeshte sits where the waters of the Zakhan River meet the Karakaz. The village makes its living from mining nearby salt deposits.[1]'),
  ('hanekhy', 'Hanekhy', 4, 'makeb', 'Iron', 139.0, 'Hanekhy sits atop a northern spur of the Akkan Hills. The reddish streaks in the soil and rocks testify to rich iron deposits, which are mined by the villagers.[1]'),
  ('mazen', 'Mazen', 4, 'makeb', 'Fish', 178.0, 'The fishing village of Mazen sits on the northern end of Lake Tanaesis, which the Khuzaits call the Tanaz Sea. The villagers set nets in the nearby Karakaz River to catch a variety of fish migrating to and from the lake.[1]'),
  ('danara', 'Danara', 4, 'odokh', 'Salt', 272.0, 'Danara sits by the salt lake that the Khuzaits know as Tsanga Nor, the pool that quenches no thirst. The villagers of these parts extract salt from the bitter waters.'),
  ('ransam', 'Ransam', 4, 'ortongard', 'Horses', 108.0, 'Ransam is in the southeastern plains of the Devseg plateau. Villagers, who not long ago still lived a nomadic lifestyle, specialize in the rearing of horses.'),
  ('mivanjan', 'Mivanjan', 4, 'ortongard', 'Sheep', 204.0, 'Mivanjan sits at the foot of the Sulun Dag mountains, that mark the eastern border of the Devseg plateau. Villagers, who not long ago still lived a nomadic lifestyle, raise sheep in the foothills.'),
  ('urunjan', 'Urunjan', 4, 'ortongard', 'Cows', 159.0, 'Urunjan near the western edge of the Devseg plateau, at the foot of the Akkan hills. Villagers raise cattle here that are bred to withstand both the hot summers and freezing winters.'),
  ('marabrot', 'Marabrot', 6, 'balgard', 'Iron', 322.0, 'Marabrot sits on a high rocky ridge between the fjord known as Mazopor Bay and the Byalic Sea. This harsh land would probably not be settled where it not for the rich iron deposits in the hills.[1]'),
  ('safna', 'Safna', 6, 'balgard', 'Cows', 112.0, 'Safna sits on a high ridge overlooking the rapids that link Lake Laconis to the narrow Mazopor Bay. Villagers rear cattle on the grassy shelfs overlooking the sea-cliffs.[1]'),
  ('chornobas', 'Chornobas', 6, 'omor', 'Grain', 125.0, 'Chornobas, or Blackwood, sits in lands cleared from the forests overlooking the cataract through which the Miron River empties into Lake Laconis. The villagers grow rye and barley in fields misted by the spray from the falls.[1]'),
  ('skorin', 'Skorin', 6, 'omor', 'Fish', 161.0, 'Skorin sits on a promontory separating Dyatom Bay from the wider Lake Laconis. Villagers pull both freshwater flatfish from the shallow bay waters and bigger catch, including pike, from the main lake.[1]'),
  ('korsyas', 'Korsyas', 6, 'revyl', 'Fish', 527.0, 'Korsyas sits near the narrowest part of the Bay of Varcheg. Villagers fish the waters to the west for cod, char, and other cold-water sea fish that venture into the bay.[1]'),
  ('karbur', 'Karbur', 6, 'revyl', 'Grain', 296.0, 'Karbur sits at a plateau on the Kachyar Peninsula. Sheltered somewhat by a high ridge to their north, the villagers here raise barley and grain.[1]'),
  ('alebat', 'Alebat', 6, 'sibir', 'Hardwood', 201.0, 'Alebat sits deep in the forests of northeastern Sturgian. This isolated region has long been a refuge for those fleeing oppression or debt or bloodfeud across the northlands, and the dialect is strongly influenced by the tongue of the Vanni woodspeople.[1]'),
  ('radakmed', 'Radakmed', 6, 'sibir', 'Cows', 339.0, 'Radakmed sits in a basin amid the Chertyg Mountains. Villagers here grow flax in the marshy valley floor.[1]'),
  ('kvol', 'Kvol', 6, 'sibir', 'Cows', 508.0, 'The villagers of Kvol raise small, sturdy cattle at the base of the Chertyg Mountains. They include the descendants of refugees and malcontents from across Calradia, seeking isolation in the cold northern forests.[1]'),
  ('bukits', 'Bukits', 6, 'tyal', 'Cows', 126.0, 'Bukits sits on the eastern slopes of Mount Iltan on the Khuzaits frontier. Villagers raise highland cattle here, bred to withstand the icy gusts that tear down the mountain.[1]'),
  ('visibrot', 'Visibrot', 6, 'tyal', 'Sheep', 530.0, 'Visibrot is a sheep-rearing village on the lower slopes of Mount Iltan, just below the network of glacial lakes known as the Portages of Iltan. Though this region is cold and remote, its importance as a trade juncture between Lake Laconis and Lake Tanaesis, between the Empire and the steppe, means that it is relatively densely populated.[1]'),
  ('kargrev', 'Kargrev', 6, 'varcheg', 'Fish', 197.0, 'Kargrev was once ''Car Gryff'', the ringfort of the 2n chief Gryff, but was conquered by the 6ns two generations ago. It lies alongside the Bay of Varcheg, where the local fishermen take advantage of the relatively sheltered waters of the bay, where fish of many kinds come to spawn.[1]'),
  ('rodobas', 'Rodobas', 6, 'varcheg', 'Furs', 311.0, 'Rodobas, meaning ''the house of Obas'', is named for a long-dead 6n hill chieftain. Perched high on a ridge overlooking the Ircara Wildlands, it serves as a base for trappers looking for furs in the dark woods below.[1]'),
  ('yangutum', 'Yangutum', 6, 'varnovapol', 'Iron Ore', 333.0, 'Yangutum sits in a nook of the Chertyg Mountains on the north shores of Lake Laconis. Villagers here have found iron ore deposits in the mountainsides.[1]'),
  ('omkany', 'Omkany', 6, 'varnovapol', 'Hogs', 283.0, 'Omkany lies where the Lake Laconis coastline rises up to meet the icy Chertyg Mountains. Villagers in this district raise hogs, curing their fat with salt and in garlic and selling it throughout the northlands.[1]'),
  ('borchovagorka', 'Borchovagorka', 6, 'varnovapol', 'Fish', 440.0, 'Borchovagorka sits on a small rise on the steep northern shores of Lake Laconis. The village depends primarily on fishing, pulling perch, bream, salmon and occasionally large sturgeon and pike from the lake waters. [1]'),
  ('savinth', 'Savinth', 7, 'charas', 'Horses', 680.0, 'Savinth is a village in Vlandian owned by the baron, Ingalther of House dey Cortain. The village is bound to Charas and is known to produce Horses.'),
  ('vesin', 'Vesin', 7, 'charas', 'Olives', 169.0, 'Vesin is a village in Vlandian owned by the baron, Ingalther of House dey Cortain. The village is bound to Charas and is known to produce Olives.'),
  ('furbec', 'Furbec', 7, 'galend', 'Grapes', 488.0, 'Furbec is a village in Vlandian owned by King Derthert of House dey Meroc. The village is bound to Galend and is known to produce Grapes.'),
  ('meroc', 'Meroc', 7, 'galend', 'Fish', 527.0, 'Meroc is a village of Vlandian owned by King Derthert of House dey Meroc. The village is bound to Galend and is known to produce Fish.'),
  ('nogrent', 'Nogrent', 7, 'galend', 'Sheep', 211.0, 'Nogrent is a village in Vlandian owned by King Derthert of House dey Meroc. The village is bound to Galend and is known to produce Sheep.'),
  ('arromanc', 'Arromanc', 7, 'jaculan', 'Olives', 120.0, 'Arromanc is a village in Vlandian owned by Calatild of House dey Arromanc. The village is bound to Jaculan and is known to produce Olives.'),
  ('mot', 'Mot', 7, 'jaculan', 'Sheep', 615.0, 'Mot is a village in Vlandian owned by Calatild of House dey Arromanc. The village is bound to Jaculan and is known to produce Sheep.'),
  ('alorstan', 'Alorstan', 7, 'jaculan', 'Olives', 157.0, 'Alorstan is a village in Vlandian owned by Calatild of House dey Arromanc. The village is bound to Jaculan and is known to produce Olives.'),
  ('chornad', 'Chornad', 7, 'jaculan', 'Pigs', 157.0, 'Chornad is a village in Vlandian owned by Calatild of House dey Arromanc. The village is bound to Jaculan and is known to produce Pigs.'),
  ('mareiven', 'Mareiven', 7, 'ocs_hall', 'Hardwood', 216.0, 'Mareiven is a village in Vlandian owned by the baron, Belgir of the House dey Fortes. The village is bound to Ocs Hall and is known to produce Hardwood.'),
  ('oritan', 'Oritan', 7, 'ocs_hall', 'Clay', 347.0, 'Oritan is a village in Vlandian owned by the baron, Belgir of the House dey Fortes. The village is bound to Ocs Hall and is known to produce Clay.'),
  ('fregian', 'Fregian', 7, 'ocs_hall', 'Flax', 347.0, 'Fregian is a village in Vlandian owned by the baron, Belgir of the House dey Fortes. The village is bound to Ocs Hall and is known to produce Flax.'),
  ('horsger', 'Horsger', 7, 'ostican', 'Fish', 454.0, 'Horsger is where, according to legend, the warrior Horsa came ashore and planted his spear in the beach. Today it is known for its daring fishermen, who venture out far to find banks, chilled by currents from the north, that are rich in cod.'),
  ('cananc', 'Cananc', 7, 'ostican', 'Grapes', 340.0, 'Cananc lies in the wet wooded hills of the northern Rhennod, where cedars grow tall in the sea-mists. The villagers trap beaver, marten and rabbit for their pelts.'),
  ('remental', 'Remental', 7, 'ostican', 'Olives', 683.0, 'Remental sits in a gap in the mountains of the Ebor peninsula. Towering fir and spruce grow on the slopes. Villagers trap fur-bearing animals like marten, rabbit and fox. This wild region has recently attracted many settlers drawn to the relative freedom of the woods, where the rule of the 7n barons is much lighter than in the south.'),
  ('alantas', 'Alantas', 7, 'rovalt', 'Iron Ore', 489.0, 'Alantas sits in the center of the mountainous Ebor peninsula. The soil here is thin and the weather here is cold, but rich iron deposits sustain the local economy.[1]'),
  ('halisvust', 'Halisvust', 7, 'rovalt', 'Grain', 282.0, 'Halisvust is a village of Vlandian owned by the baron, Servic of House dey Valant. The village is bound to Rovalt and it is known to produce Grain.'),
  ('calioc', 'Calioc', 7, 'sargot', 'Flax', 132.0, 'Calioc is a village in Vlandian owned by King Derthert of House dey Meroc. The village is bound to Sargot and is known to produce Flax.'),
  ('etirburg', 'Etirburg', 7, 'sargot', 'Grain', 0.0, 'Etirburg  Settlement Information  Type Village   Kingdom Vlandian   Fortification Sargot    Etirfurd is a village in Vlandian owned by King Derthert of House dey Meroc. The village is bound to Sargot and is known to produce Grain.'),
  ('avasinton', 'Avasinton', 3, 'amprela', 'Cotton', 340.0, 'Avasinton is a village of the Northern Empire owned by Encurion of the Impestores clan. The village is bound to Amprela and it is known to produce Cotton.'),
  ('boreagora', 'Boreagora', 3, 'amprela', 'Flax', 411.0, 'Boreagora lies in the cold north of the Empire, by the network of glacial lakes known as the Portages of Iltan. Nearby imperial forts, looming over the waterways, keep watch for 6n and Khuzait raiders. The lowlands here are suited to the growing of flax.[1]'),
  ('alatys', 'Alatys', 3, 'argoron', 'Fish', 646.0, 'Alatys is a village in the Northern Empire owned by Emperor Lucon of clan Osticos. The village is bound to Argoros and is known to produce Fish.'),
  ('hetania', 'Hetania', 3, 'argoron', 'Hardwood', 346.0, 'Hetania is a village in the Northern Empire owned by Emperor Lucon of clan Osticos. The village is bound to Argoros and is known to produce Hardwood.'),
  ('alosea', 'Alosea', 3, 'diathma', 'Fish', 532.0, 'Alosea lies near the entrance of the Diathmic Bay, on the far western end of Lake Laconis. The folk of this region live well off the pike and sturgeon of the lake.[1]'),
  ('jeracos', 'Jeracos', 3, 'diathma', 'Horses', 705.0, 'Jeracos sits in meadowland in the northern piedmont of the Dryatic mountains. The climate, kept mild by the lake breezes, makes for good horse breeding.[1]'),
  ('gymos', 'Gymos', 3, 'epicrotea', 'Fish', 125.0, 'Gymos is a quiet fishing village in the Diathmic Bay, on the far west of Lake Laconis. Villagers harvest pike from the bay''s deep waters.[1]'),
  ('marathea', 'Marathea', 3, 'epicrotea', 'Iron Ore', 322.0, 'Marathea lies on a narrow shelf of land between the Miron River and Mount Aracathos, the tallest peak in the Dryatic Mountains. The villagers are skilled miners, extracting iron ores from the nearby cliffside.[1]'),
  ('stathymos', 'Stathymos', 3, 'epicrotea', 'Grain', 125.0, 'Stathymos lies in a narrow valley beneath a towering ridge of the Dryatic Mountains. The highland streams wash fertile soil down the hillsides, making this district one of the breadbaskets of the imperial north.[1]'),
  ('orthra', 'Orthra', 3, 'myzea', 'Horses', 305.0, 'Orthra is a village of the Northern Empire owned by the archon Gyphor of the Dolentos clan. The village is bound to Myzea and is known to produce Horses.'),
  ('samatha', 'Samatha', 3, 'myzea', 'Raw Silk', 170.0, 'Samatha sits upon a sloping ridge in the sun-drenched highlands of the Myzead. The hillsides have been terraced to allow the growing of mulberry bushes. The leaves are harvested, placed in vats and fed to silkworms.[1]'),
  ('vealos', 'Vealos', 3, 'myzea', 'Horses', 221.0, 'Vealos is a village of the Northern Empire owned by the archon Gyphor of the Dolentos clan. The village is bound to Myzea and is known to produce Horses.'),
  ('crios', 'Crios', 3, 'saneopa', 'Horses', 145.0, 'Crios is a village of the Northern Empire owned by the archon Penton of the Neretzes clan. The village is bound to Saneopa and known to produce Horses.'),
  ('enoisa', 'Enoisa', 3, 'saneopa', 'Grain', 275.0, 'Enoisa is a village of the Northern Empire owned by the archon Penton of the Neretzes clan. The village is bound to Saneopa and known to produce Grain.'),
  ('ain_baliq', 'Ain Baliq', 1, 'ain_baliq_castle', 'Horses', 375.0, 'Ain Baliq is clustered around a well in a wide valley that separates the Jarjara Escarpment from the Jabal Tamar Mountains to the west. The surrounding lands, though dry, produce enough grass in the spring to allow the breeding of horses.[1]'),
  ('deir_hawa', 'Deir Hawa', 1, 'ain_baliq_castle', 'Silver Ore', 375.0, 'Deir Hawa sits on the windswept southern shores of the sea that the Aserai call the Bahr al-Yeshm. Villagers trap run-off water from the hills and grow flax in the lowlands here.[1]'),
  ('barihal', 'Barihal', 1, 'barihal_castle', 'Horses', 202.0, 'The oasis-village of Barihal sits in a wadi amid the mesas of the Jarjara Escarpment. The land is best known for the horses that are grazed on the desert''s short-lived but rich spring grasses.[1]'),
  ('wadar', 'Wadar', 1, 'barihal_castle', 'Horses', 305.0, 'Wadar sits in the rocky wadis at the inland edge of the Jarjara Escarpment, before it gives way to barren gravel plains and dunes. Clouds from the Bahr al-Yeshm drop their last reserves of water here in the spring and winter, giving the land just enough grass to support horse-rearing.[1]'),
  ('jamayeh', 'Jamayeh', 1, 'jamayeh_castle', 'Olives', 610.0, 'Jamayeh sits on the southern shores of the sea that the Aserai call the Bahr al Yeshm, the Jade Sea. The climate is well-suited to olive trees that thrive despite the short rainy season. [1]'),
  ('hunab', 'Hunab', 1, 'jamayeh_castle', 'Dates', 370.0, 'Hunab is a village in the Aserai Sultanate ruled by the emir Suruq of the Banu Qaraz. The village is bound to Jamayeh Castle and is known to produce Dates.'),
  ('medeni', 'Medeni', 1, 'medeni_castle', 'Dates', 540.0, 'Medeni sits in lowlands between the Bahr al-Yeshm sea and the Jarjara Escarpment. Villagers grow dates by the coast in gardens watered by wells and small dams in the wadis that trap run-off from the cliffs during the short rainy season. [1]'),
  ('qidnar', 'Qidnar', 1, 'medeni_castle', 'Grain', 540.0, 'Qidnar lies in the floodplain of the Damar River, the most densely populated part of the Aserai lands, where it slices through the Jarjara Escarpment. Farmers here grow grain in the rich silt brought by the river''s annual flooding. [1]'),
  ('sahel', 'Sahel', 1, 'sahel_castle', 'Grain', 401.0, 'Sahel is a village of the Aserai owned by Emir Tais of the Banu Qild. The village is bound to Sahel Castle and known to produce Grain.'),
  ('asmait', 'Asmait', 1, 'sahel_castle', 'Dates', 401.0, 'Asmait lies in a nook of the Jabal Ashabi Mountains, bordered to the south by the deep desert. Villagers trap floods running down the hills during rare rainstorms, using the water to grow date palms and other crops.[1]'),
  ('shibal_zumr', 'Shibal Zumr', 1, 'shibal_zumr_castle', 'Grain', 120.0, 'Shibal Zumr sits on the Nahr al-Kals, the river of lime. Here the waters are pure and the soil is fertile, and grain is grown. But a short distance to the south, the land becomes barren and alkaline, and only the hardiest crops survive.[1]'),
  ('lamesa', 'Lamesa', 1, 'shibal_zumr_castle', 'Desert Horses', 327.0, 'Lamesa sits amid open plains and patches of dry acacia forest on the eastern shores of the Bahr al-Yeshm. Some of the Aserai''s most prized horses graze on the grasses of this district.[1]'),
  ('tamnuh', 'Tamnuh', 1, 'tamnuh_castle', 'Clay', 352.0, 'Tamnuh sits near a large lagoon, cut off from the Perassic Sea by a sandspit. Villagers scrape clay from the shallow waters to sell to the region''s potters.[1]'),
  ('kuqa', 'Kuqa', 1, 'tamnuh_castle', 'Dates', 454.0, 'Kuqa sits at the foot of a range of low hills east of the Bahr al-Yeshm sea, where the Aserai deserts give way to desert-steppe with scattered acacia and scrub. The villagers here sink wells to water their groves of date palms.[1]'),
  ('fanab', 'Fanab', 1, 'tubilis_castle', 'Flax', 137.0, 'Fanab sits in a low promontory between the bay that the Aserai call the Gulf of Shiraz and the inner sea of the Bahr al-Yeshm.  The seawinds bring just enough rain to support the cultivation of olive trees.[1]'),
  ('tubilis', 'Tubilis', 1, 'tubilis_castle', 'Fish', 148.0, 'Tubilis lies on the Gulf of Charas, which the Aserai call the Gulf of Shariz. Villagers go fishing here amid the offshore islands in search of tuna, sardines, and shark.[1]'),
  ('uqba', 'Uqba', 1, 'uqba_castle', 'Dates', 477.0, 'Uqba sits alongside the Perassic Sea. Villagers trap rainwater and runoff from the hills to water their fields and their gardens of date-palms.[1]'),
  ('bunqaz', 'Bunqaz', 1, 'uqba_castle', 'Olives', 477.0, 'Bunqaz sits at the mouth of the great wadi that divides the Jarjara Escarpment from the Jabal Tamar Mountains. Villagers sink wells here to tap the wadi''s groundwater, using it to irrigate their olive groves.[1]'),
  ('ab_comer', 'Ab Comer', 2, 'ab_comer_castle', 'Grapes', 125.0, 'Ab Comer is a village in Battanian owned by Mormaer Maireas of clan fen Caernacht. The village is bound to Ab Comer Castle and known to produce Grapes.'),
  ('inveth', 'Inveth', 2, 'ab_comer_castle', 'Grain', 468.0, 'Inveth is a village in Battanian owned by Mormaer Maireas of clan fen Caernacht. The village is bound to Ab Comer Castle and known to produce Grain.'),
  ('aster', 'Aster', 2, 'aster_castle', 'Flax', 809.0, 'Aster is a village within the lands of Battanian owned by the chieftain Ergeon of Clan fen Derngil. The village is bound to Aster Castle and known to produce Flax.'),
  ('imlagh', 'Imlagh', 2, 'aster_castle', 'Grapes', 218.0, 'Imlagh is a village within the lands of Battanian owned by the chieftain Ergeon of Clan fen Derngil. The village is bound to Aster Castle and known to produce Grapes.'),
  ('druimmor', 'Druimmor', 2, 'druimmor_castle', 'Silver Ore', 110.0, 'Druimmor is a village of Battanian owned by the chieftain Aradwyr of the Clan fen Eingal.  The village is bound to Druimmor Castle and is known to produce Silver Ore.'),
  ('tor_melina', 'Tor Melina', 2, 'druimmor_castle', 'Cotton', 357.0, 'Tor Melina is a village of Battanian owned by the chieftain Aradwyr of clan fen Eingal. The village is bound to Druimmor Castle and is known to produce Cotton.'),
  ('flintolg', 'Flintolg', 2, 'flintolg_castle', 'Hardwood', 374.0, 'Flintolg is a village within the lands of Battanian owned by the chieftain Luichan of Clan fen Penraic. The village is bound to Flintolg Castle and it is known to produce Hardwood.'),
  ('glintor', 'Glintor', 2, 'flintolg_castle', 'Horses', 374.0, 'Glintor sits overlooking the rapids of the Fiur river, where the waters of Llyn Tywal descend to enter the Bay of Varcheg. Horses are raised on the downs, much prized by both raiders and traders from the 6n lands to the north.'),
  ('llanoc_hen', 'Llanoc Hen', 2, 'llanoc_hen_castle', 'Hogs', 319.0, 'Llanoc Hen sits in a ridge in the heights of the Uchalion massif. The villagers, known as skilled pig-farmers, look down two passes, the western one leading up from 7n lands and the eastern one leading up from the Empire.[1]'),
  ('cantrec', 'Cantrec', 2, 'llanoc_hen_castle', 'Hogs', 347.0, 'Cantrec sits in the rocky Glen of Balasog that climbs up from the imperial lands into the plateau of the Uchalion. The lands is not especially fertile here, but pigs thrive in the bush and shrubland of the heights.[1]'),
  ('pendraic', 'Pendraic', 2, 'pendraic_castle', 'Grain', 150.0, 'DANK OHIO Pendraic sits on the steep northern slope of the Uchalion Plateau, facing the Bay of Varcheg. It is a land of cold winds and constant low-level warfare, criss-crossed by 7n, 2n and 6n raiding parties. The villagers raise hogs here, always listening to the warning horns telling them to drive their herds to hiding spots in the hills.[1]'),
  ('lindorn', 'Lindorn', 2, 'pendraic_castle', 'Grain', 118.0, 'Lindorn sits on the green hills north and west of Llyn Tywal, the dark lake. The surrounding farmlands are sown with wheat and barley.[1]'),
  ('rhemtoil', 'Rhemtoil', 2, 'rhemtoil_castle', 'Grain', 307.0, 'Rhemtoil is a village in Battanian owned by High King Caladog of clan fen Gruffendoc. The village is bound to Rhemtoil Castle and known to produce Grain.'),
  ('claig_ban', 'Claig Ban', 2, 'rhemtoil_castle', 'Clay', 347.0, 'Claig Ban is a village in Battanian owned by High King Caladog of clan fen Gruffendoc. The village is bound to Rhemtoil Castle and known to produce Clay.'),
  ('uthelaim', 'Uthelaim', 2, 'uthelaim_castle', 'Hardwood', 697.0, 'Uthelaim is a village in Battanian owned by High King Caladog of clan fen Gruffendoc. The village is bound to Uthelaim Castle and known to produce Hardwood.'),
  ('seordas', 'Seordas', 2, 'uthelaim_castle', 'Grain', 328.0, 'Seordas is a village in Battanian owned by High King Caladog of clan fen Gruffendoc. The village is bound to Uthelaim Castle and known to produce Grain.'),
  ('akiser', 'Akiser', 4, 'akiser_castle', 'Iron Ore', 194.0, 'Akiser sits in the southern reaches of the Akkan hills. The land here is exceptionally broken and weathered, revealing seams of iron in the sides of the gullies and ravines.'),
  ('dinar', 'Dinar', 4, 'dinar_castle', 'Sheep', 240.0, 'Dinar lies in the far north of the Khuzaits confederacy, along the Karakaz river. Snow-bound for much of the year, the spring grasses nonetheless sustain sizeable herds of sheep, the thick wool of which protects them from this land''s icy winds.'),
  ('karahalli', 'Karahalli', 4, 'dinar_castle', 'Sheep', 415.0, 'Karahalli lies in the far north of the Khuzaits confederacy, not far from the icy Byalic Sea. Snow-bound for much of the year, the spring grasses nonetheless sustain sizeable herds of sheep, the thick wool of which protects them from the icy winds blowing off of the waters.'),
  ('erzenur', 'Erzenur', 4, 'erzenur_castle', 'Iron Ore', 370.0, 'Erzenur alongside the River Tiagys, known in the local dialect as the ''Teyagh''. The waters here have a distinct reddish tint from the iron in the soil, which the villagers mine from riverside outcrops.[1]'),
  ('gereden', 'Gereden', 4, 'erzenur_castle', 'Clay', 272.0, 'Gereden and its outlying hamlets on the southern end of the Devseg Plateau, near the juncture of Ozu River and Teyagh River. Though rough country, it is known for the fine clay that can be gathered from the ravines. [1]'),
  ('hakkun', 'Hakkun', 4, 'hakkun_castle', 'Silver Ore', 132.0, 'The village of Hakkun is perched atop the escarpment of the Akkan Hills. The people of these parts have long mined silver from the mountains, a trade that the Khuzaits khans were happy to encourage when they conquered this region. [1]'),
  ('kiraz', 'Kiraz', 4, 'hakkun_castle', 'Sheep', 253.0, 'Kiraz lies in a basin at the southern end of the Devseg Plateau. Until recently, this land was dominated by nomads, and the people here still make their living by raising sheep. [1]'),
  ('kaysar', 'Kaysar', 4, 'kaysar_castle', 'Cows', 339.0, 'Kaysar sits in the north and east of the lands ruled by the 4s, in the valley of the Karakaz river. This district is snowbound for much of the year, but villagers still raise herds of cattle bred to withstand the icy winds coming downriver from the north.'),
  ('payam', 'Payam', 4, 'kaysar_castle', 'Wheat', 204.0, 'Payam lies alongside the Karakaz river in the cold north of the Khuzaits lands. Though the land is snowbound much of the year, the villagers sow wheat and barley as soon as the melt starts, taking in a good crop before the autumn.'),
  ('omrotok', 'Omrotok', 4, 'khimli_castle', 'Hardwood', 370.0, 'Omrotok sits at the foot of the Sulun Dag mountains, that mark the eastern border of the Devseg plateau. Villagers go to the nearby woods to harvest one of the Devseg''s few sources of timber.'),
  ('simira', 'Simira', 4, 'simira_castle', 'Cows', 177.0, 'Simira sits near the east of the Devseg plateau, as it begins to descend into the great grass sea of the east. Villagers here raise cattle bred to withstand both cold winters and hot summers.'),
  ('kohi_ajik', 'Kohi Ajik', 4, 'simira_castle', 'Horses', 230.0, 'Kohi Ajik lies in a narrow, dry valley at the foot of the so-called Lover''s Mountain, from which its name derives. The peoples of this land buy horses from the nomads to their east and sell them to the Khuzaits aristocracy in the towns.'),
  ('usek', 'Usek', 4, 'usek_castle', 'Sheep', 130.0, 'Usek sits at the foot of the Akkan hills on the eastern shores of Lake Tanaesis, which the Khuzaits call the Tanaz Sea. The villagers, who until recently were nomads, raise sheep known for their long, fine wool.'),
  ('esme', 'Esme', 4, 'usek_castle', 'Horses', 106.0, 'The village of Esme and its surrounding hamlets lie on the landward side of the Akkan hills on the Devseg plateau, prime grazing lands for the flocks of the Khuzaits and their confederates.'),
  ('forin', 'Forin', 6, 'mazhadan_castle', 'Grain', 293.0, 'Forin is a village in Sturgian owned by Grand Prince Raganvad of clan Gundaroving. The village is bound to Mazhadan Castle and known to produce Grain.'),
  ('mazhadan', 'Mazhadan', 6, 'mazhadan_castle', 'Flax', 270.0, 'Mazhadan sits near the source of the Galchas River, just west of Lake Laconis. Villagers grow flax in the muddy valleys between the hills in this cold, rainy land.[1]'),
  ('dnin', 'Dnin', 6, 'nevyansk_castle', 'Horses', 186.0, 'Dnin sits on pastures overlooking the narrowest part of the Bay of Varcheg. Horses graze on the heights, glancing down occasionally at the trading longships and fishing boats passing beneath them.[1]'),
  ('nevyansk', 'Nevyansk', 6, 'nevyansk_castle', 'Grain', 106.0, 'Nevyansk sits on a flat shelf of land overlooking the Bay of Varcheg. The land is cold, but the runoff from the hills brings rich soil, and villagers grow hardy crops like rye and barley.[1]'),
  ('ov', 'Ov', 6, 'ov_castle', 'Furs', 403.0, 'Ov is a recent 6n colony in the Ircara wilds, a forest northwest of Lake Laconis. Villagers brave cold, wolves and the sometimes-hostile, sometimes-friendly peoples of the woods in pursuit of fur, the bounty of the northlands.[1]'),
  ('takor', 'Takor', 6, 'takor_castle', 'Cows', 544.0, 'Takor is a cattle raising village at the pass that the 2ns call ''Mynad Rhyfel'', the mountain of war, and their imperial and 6n neighbors call Minador. It is one of the main trading and raiding routes between the wild north and the more settled imperial lands.[1]'),
  ('dvorusta', 'Dvorusta', 6, 'takor_castle', 'Fish', 219.0, 'Dvorusta is a fishing village overlooking the rapids linking Mazopor Bay with Lake Laconis. Villagers make their way down the cliffsides at dawn to catch salmon leaping over the rocks, as well as herring and cod in the sea.[1]'),
  ('urikskala', 'Urikskala', 6, 'urikskala_castle', 'Fish', 572.0, 'Urikskala sits in the Portages of Iltan, a network of glacial lakes over which longships can be hauled and sailed between Lake Laconis and Lake Tanaesis. Villagers net small spiny perch and crayfish in the shallow waters, drying them for sale to travelers.[1]'),
  ('alov', 'Alov', 6, 'urikskala_castle', 'Grain', 157.0, 'Alov sits on the edge of the glacial lakes known as the Portages of Iltan. Villagers cultivate rye and barley on the high ground overlooking the lakes, and the rich black soil of the region compensates for the long winters and short growing season.[1]'),
  ('vladiv', 'Vladiv', 6, 'vladiv_castle', 'Cows', 152.0, 'Vladiv sits at the base of Mount Iltan, in a cold, dark wooded valley. The hardy cattle of this region have learned to dig through thick winter snows in search of grass to sustain them until the spring.[1]'),
  ('caleus', 'Caleus', 7, 'caleus_castle', 'Flax', 429.0, 'Caleus lies on the misty coastal plain south of the Bay of Varcheg. Villagers speak a mix of the 7n, 6n and 2n tongues. They grow flax in the lowlands here.[1]'),
  ('deriat', 'Deriat', 7, 'caleus_castle', 'Olives', 429.0, 'Deriat is a village in Vlandian owned by Baron Servic of House dey Valant. The village is bound to Caleus Castle and known to produce Olives.'),
  ('drapand', 'Drapand', 7, 'drapand_castle', 'Olives', 285.0, 'Drapand is a village in Vlandian owned by the baron, Aldric of the House dey Tihr. The village is bound to Drapand Castle and is known to produce Olives.'),
  ('valanby', 'Valanby', 7, 'drapand_castle', 'Olives', 280.0, 'Valanby is a village in Vlandian owned by the baron, Aldric of the House dey Tihr. The village is bound to Drapand Castle and is known to produce Olives. It is likely that the town is famous for its horses and the namesake of the Valanby Courser breed.'),
  ('hongard', 'Hongard', 7, 'hongard_castle', 'Grain', 400.0, 'Hongard is a village in Vlandian owned by the baron, Vartin of House dey Jelind. The village is bound to Hongard Castle and is known to produce Grain.'),
  ('ferton', 'Ferton', 7, 'hongard_castle', 'Olives', 400.0, 'Ferton is a village in Vlandian owned by the baron, Vartin of House dey Jelind. The village is bound to Hongard Castle and is known to produce Olives.'),
  ('ormanfard', 'Ormanfard', 7, 'ormanfard_castle', 'Grain', 170.0, 'Ormanfard sits by a small, fast-flowing river that runs down from the mountains of the Rhennod to fill the lake known as Ocspool. Rains are plentiful and wheat and barley grow well on the hillsides.'),
  ('talivel', 'Talivel', 7, 'talivel_castle', 'Olives', 667.0, 'Talivel is a village in Vlandian owned by King Derthert of House dey Meroc. The village is bound to Talivel Castle and known to produce Olives.'),
  ('rodetan', 'Rodetan', 7, 'talivel_castle', 'Iron Ore', 264.0, 'Rodetan is a village in Vlandian owned by King Derthert of House dey Meroc. The village is bound to Talivel Castle and is known to produce Iron Ore.'),
  ('tirby', 'Tirby', 7, 'tirby_castle', 'Silver Ore', 640.0, 'Tirby is a village in Vlandian owned by the baron, Ospir of the House dey Gunric. The village is bound to Tirby Castle and known to produce Silver Ore.'),
  ('sirindac', 'Sirindac', 7, 'tirby_castle', 'Flax', 640.0, 'Sirindac is a village in Vlandian owned by the baron, Ospir of the House dey Gunric. The village is bound to Tirby Castle and known to produce Flax.'),
  ('usanc', 'Usanc', 7, 'usanc_castle', 'Olives', 498.0, 'Usanc is a village in Vlandian owned by Baron Berican of House dey Rothad. The village is bound to Usanc Castle and known to produce Olives.'),
  ('verecsand', 'Verecsand', 7, 'verecsand_castle', 'Grain', 230.0, 'Verecsand sits by the waters of the Ocspool, a small but deep inland lake. Villagers here grow wheat in the gentle downs by the lakeside.'),
  ('marin', 'Marin', 7, 'verecsand_castle', 'Grapes', 341.0, 'Marin is a village in Vlandian owned by the baron, Belgir of the House dey Fortes. The village is bound to Verecsand Castle and is known to produce Grapes.'),
  ('ataconia', 'Ataconia', 3, 'ataconia_castle', 'Silver Ore', 682.0, 'Ataconia sits on a plateau in the piedmont of the Dryatic Mountains. The people of this area are skilled at finding seams of silver ore exposed by the streams rushing down from the mountains. [1]'),
  ('potamis', 'Potamis', 3, 'ataconia_castle', 'Cows', 577.0, 'Potamis is a village of the Northern Empire owned by Manteos of the Argoron clan.  The village is bound to Ataconia Castle and is known to produce Cows.'),
  ('masangara', 'Masangara', 3, 'atriom_castle', 'Cows', 652.0, 'Masangara sits on the banks of the Nevys, a cold, slow-moving river that empties into Lake Laconis. Cattle are raised here in former marshy woodlands, now drained and turned into meadows.[1]'),
  ('gaos', 'Gaos', 3, 'gaos_castle', 'Cows', 367.0, 'Gaos sits in a broad valley in the Myzead, the hill country in the east of the Empire. Nomadic herders once occupied this land, and the village''s name is taken from their word for cattle.[1]'),
  ('themys', 'Themys', 3, 'gaos_castle', 'Sheep', 670.0, 'Themys lies under a ridge of limestone crags in the Myzead, the hill country of the imperial heartland. The grasses on the rolling downs are well-suited to the raising of sheep.[1]'),
  ('epinosa', 'Epinosa', 3, 'epinosa_castle', 'Cows', 222.0, 'Epinosa is a village of the Northern Empire owned by Tasynor of the Phalentes clan. The village is bound to Epinosa Castle and known to produce Cows.'),
  ('pons', 'Pons', 3, 'epinosa_castle', 'Cows', 722.0, 'Pons is a village of the Northern Empire owned by Tasynor of the Phalentes clan. The village is bound to Epinosa Castle and known to produce Cows.'),
  ('lochana', 'Lochana', 3, 'lochana_castle', 'Raw Silk', 557.0, 'Lochana sits on the eastern shore of Lake Laconis. The muddy, low-lying land here is well suited to the growing of flax.[1]'),
  ('nortanisa', 'Nortanisa', 3, 'lochana_castle', 'Fish', 346.0, 'Nortansia  Settlement Information  Type Village   Kingdom Northern Empire   Fortification Lochana Castle    Nortansia is a village of the Northern Empire owned by Nicasor of the Chonis clan. The village is bound to Lochana Castle and known to produce Fish.'),
  ('agalmon', 'Agalmon', 3, 'mecalovea_castle', 'Hardwood', 589.0, 'Agalmon sits near the juncture of the Galchas River and the Miron River, two small but fast-flowing northern rivers. This foresting village has had mostly good relations with its 6n neighbors thanks to decades of intermarriage, though they have become strained of late with the outbreak of war.[1]'),
  ('mecalovea', 'Mecalovea', 3, 'mecalovea_castle', 'Iron Ore', 389.0, 'Mecalovea sits overlooking the Galchasic Cataracts, a series of rapids and waterfalls through which the Miron River empties into Lake Laconis. The village, perched on a cliffside for protection from raiders in this frontier region, thrives on the ore deposits exposed where the cataract cuts through the escarpment.[1]'),
  ('rhesos', 'Rhesos', 3, 'rhesos_castle', 'Cows', 610.0, 'Rhesos sits in a plateau in the Dryatic Mountains. Highland cattle thrive on the grasses of the heights.[1]'),
  ('dyopalis', 'Dyopalis', 3, 'rhesos_castle', 'Grain', 125.0, 'Dyopalis lies in a valley in the Dryatic Mountains. Despite the cold winters, the region''s fertile soils make this district one of the breadbaskets of the northern Empire.[1]'),
  ('syratos', 'Syratos', 3, 'syratos_castle', 'Iron Ore', 422.0, 'Syratos is a village of the Northern Empire owned by Archon Maritzios of clan Vatatzes. The village is bound to Syratos Castle and known to produce Iron Ore.'),
  ('tememos', 'Tememos', 3, 'syratos_castle', 'Hardwood', 422.0, 'Tememos is a village in the Northern Empire owned by Archon Maritzios of clan Vatatzes. The village is bound to Syratos Castle and known to produce Hardwood.'),
  ('aeoria', 'Aeoria', 3, 'varagos_castle', 'Grain', 221.0, 'Aeoria is a village of the Northern Empire owned by the archon Penton of the Neretzes clan. The village is bound to Varagos Castle and it is known to produce Grain.'),
  ('varagos', 'Varagos', 3, 'varagos_castle', 'Sheep', 322.0, 'Varagos sits on the Aris River, a small highland stream that flows into the deep pool known as the Ophthys. The land here is not especially rich, but is sufficient for the raising of sheep.[1]'),
  ('chanopsis', 'Chanopsis', 3, 'chanopsis_castle', 'Grain', 582.0, 'Chanopsis sits near the headwaters of the Sethys River in the plateau region known as the Myzead. Wheat grows well on the sun-baked plains.[1]'),
  ('popsia', 'Popsia', 3, 'chanopsis_castle', 'Hardwood', 203.0, 'Popsia is located in a narrow canyon between the Ornian Rock and the valley of the Ophthys pool. Trees grow tall here in the cool shadows of the hills, and villagers harvest pines for sale as lumber.[1]'),
  ('corenia', 'Corenia', 3, 'corenia_castle', 'Grain', 258.0, 'Corenia is one of the farthest flung villages of the Empire to speak the Calradic tongue. It sits in the plains southeast of Lake Tanaesis in the shadow of the Akkan Hills, beyond which is spoken only Darshi and the languages of the steppe. Villagers grow grain here, keeping watch for raiders from across the frontiers.[1]'),
  ('metachia', 'Metachia', 3, 'corenia_castle', 'Raw Silk', 258.0, 'Metachia is the lies on the southern shores of Lake Tanaesis in the frontier lands beyond River Tiagys. This imperial colony, established in more peaceful times, is a center for mulberry bushes used in silk production.[1]'),
  ('jogurys', 'Jogurys', 3, 'jogurys_castle', 'Olives', 303.0, 'Jogurys lies on the flat western shores of Lake Tanaesis. This land was originally inhabited by nomadic tribes and has come under cultivation only recently. Imperial colonists have made intensive efforts to grow mullberry bushes here to raise silkworms, a lucrative product in this region.[1]'),
  ('eunalica', 'Eunalica', 3, 'jogurys_castle', 'Salt', 256.0, 'Eunalica sits on the western shores of Lake Tanaesis. This low-lying country is fine land for the growing of flax.[1]'),
  ('ethemisa', 'Ethemisa', 3, 'lavenia_castle', 'Grain', 378.0, 'Ethemisa sits on the river that the Aserai call the Nahr al-Kals, the Bitter River, and what imperial citizens call the Calsa River. Here, the river has just descended from the coastal hills and has not yet reached the alkali plains of the southeast. The lands around produce a fine crop of grain.  [1]'),
  ('lavenia', 'Lavenia', 3, 'lavenia_castle', 'Fish', 378.0, 'Lavenia is a fishing village on the northeastern shores of the Perassic Sea. The nearby castle guards one of the main passages over the network of lakes and salt lagoons known as the Calsea, one of the gateways to Aserai lands. [1]'),
  ('melion', 'Melion', 3, 'melion_castle', 'Raw Silk', 448.0, 'Melion in a narrow valley near the center of the Myzead, a rugged plateau in the east of the Empire. Villagers here cultivate mulberry bushes. The leaves are harvested and fed to silkworks, producing thread much valued by both refined imperial nobles for their courtwear and hard-riding nomads and frontiersmen, who wear it beneath their armor as an extra layer of protection against arrows. [1]'),
  ('sagolina', 'Sagolina', 3, 'melion_castle', 'Silver Ore', 448.0, 'Sagolina sits at the foot of a narrow valley in the Myzead, a rugged plateau in eastern Calradia. The silver mined from nearby hills helps explain the effort and expense to which the Empire has gone in past centuries to conquer and defend these lands. [1]'),
  ('atphynia', 'Atphynia', 3, 'morenia_castle', 'Salt', 130.0, 'The village of Atphynia sits near the mouth of the Sethys River, just before it splits into three to form the valley known as Tripotamia. Villagers here have laid out salt pans near where the Sethys estuary joins the Perassic Sea.[1]'),
  ('morenia', 'Morenia', 3, 'morenia_castle', 'Clay', 497.0, 'Morenia sits overlooking the Sethys River, on a low pass leading over the hills to the Lycarea Valley. Villagers collect clay from the riverbanks for the kilns of the imperial southlands.  [1]'),
  ('odrysa', 'Odrysa', 3, 'odrysa_castle', 'Hardwood', 272.0, 'Odrysa lies on the far eastern frontiers of the Empire, just across the River Tiagys from lands that are now the Khuzaits Khanate. Though this area is dry, oak and other trees grow in the Tiagys gorges and other nooks in the hills, sustaining a small lumber industry.[1]'),
  ('caira', 'Caira', 3, 'odrysa_castle', 'Grain', 304.0, 'Caira sits amid the network of rivers, lakes and lagoons known as the Calsea. Any further east, the land becomes alkaline and barren, but here the floodplains of the parallel Calsa River and Tiagys River allow the growing of wheat.[1]'),
  ('amycon', 'Amycon', 3, 'sestadaim_castle', 'Sheep', 133.0, 'Amycon lies in a series of small but sharp ridges between the Ornian Rock and the Aris Valley. The people of this land are sheep herders, known for their dry, salty cheese flavored with cumin.[1]'),
  ('sestadaim', 'Sestadaim', 3, 'sestadaim_castle', 'Silver Ore', 158.0, 'Sestadaim sits on the western side of the great Ornian Rock, an outcrop in the center of the Lycarea Valley. Some say the vultures for which the rock is named once gathered here to feast on the bodies of those who died working the local silver mines.[1]'),
  ('garontor', 'Garontor', 3, 'garontor_castle', 'Horses', 166.0, 'Garontor gives its name to the promontory between the Gulf of Charas and the inland Perassic Sea. Coastal meadows, where tall grasses tolerant of the ocean salt-spray thrive, support the rearing of fine horses.'),
  ('lysia', 'Lysia', 3, 'garontor_castle', 'Salt', 155.0, 'Lysia is a village of the Western Empire owned by Apys of the Varros clan. The village is bound to Garontor Castle and it is known to produce Salt.'),
  ('gersegos', 'Gersegos', 3, 'gersegos_castle', 'Silver Ore', 201.0, 'Gersegos sits in the gorges of the Miron river, as it cuts between the cliffs of the Cursion Escarpment and the Dryatic mountains. Villagers have sunk mines into a spur that overlooks the village, extracting silver and other precious metals.[1]'),
  ('vathea', 'Vathea', 3, 'gersegos_castle', 'Iron Ore', 104.0, 'Vathea sits high on the slopes of the Dryatic mountains, facing across the valley to the great basalt slab of Mount Erithrys. The villagers mine iron from shafts sunk deep into the cliffs of the mountains.[1]'),
  ('hertogea', 'Hertogea', 3, 'hertogea_castle', 'Iron Ore', 347.0, 'Hertogea is a village of Western Empire owned by Vipon of the Maneolis clan. The village is bound to Hertogea Castle and known for the production of Iron Ore.'),
  ('nideon', 'Nideon', 3, 'hertogea_castle', 'Olives', 165.0, 'Nideon is a village of Western Empire owned by by Vipon of the Maneolis clan. The village is bound to Hertogea Castle and known for the production of Olives.'),
  ('onica', 'Onica', 3, 'onica_castle', 'Olives', 312.0, 'Onica is a village in the Western Empire owned by Emperor Garios of clan Comnos. The village is bound to Onica Castle and known to produce Olives.'),
  ('tarcutis', 'Tarcutis', 3, 'onica_castle', 'Grapes', 546.0, 'Tarcutis is a village in the Western Empire owned by Emperor Garios of clan Comnos. The village is bound to Onica Castle and is known to produce Grapes.'),
  ('oristocorys', 'Oristocorys', 3, 'oristocorys_castle', 'Furs', 603.0, 'Oristocorys is a village in the Western Empire owned by Archon Vincantios of clan Palladios. The village is bound to Oristocorys Castle and known to produce Furs.'),
  ('elvania', 'Elvania', 3, 'oristocorys_castle', 'Furs', 603.0, 'Elvania is a village in the Western Empire owned by Archon Vincantios of clan Palladios. The village is bound to Oristocorys Castle and known to produce Furs.'),
  ('thorios', 'Thorios', 3, 'thorios_castle', 'Grain', 232.0, 'Thorios sits in the Aris valley in the heart of Calradia. River irrigation and the relatively warm inland climate ensure that the grain fields of this district, along with neighboring Bergum, feed much of the central Empire.[1]'),
  ('bergum', 'Bergum', 3, 'thorios_castle', 'Grain', 232.0, 'Bergum sits in the Aris valley in the heart of Calradia. River irrigation and the relatively warm inland climate ensure that the grain fields of this district, along with neighboring Thorios, feed much of the central Empire.[1]'),
  ('thractorae', 'Thractorae', 3, 'thractorae_castle', 'Dates', 346.0, 'Thractorae sits on a small bay that feeds into the larger Gulf of Charas. These lands, stirred by hot winds from the south and watered by hillside springs, have been used by imperial landowners for the experimental growing of date palms.'),
  ('gamardan', 'Gamardan', 3, 'thractorae_castle', 'Grapes', 427.0, 'Gamardan sits at the head of a small bay that branches off the larger Gulf of Charas. The wines of this region are unusually sweet and strong, and valued throughout the Empire.'),
  ('goleryn', 'Goleryn', 3, 'veron_castle', 'Sheep', 421.0, 'Goleryn is a village of Western Empire owned by by Achios of the Corenios. The village is bound to Veron Castle and it is know for the production of Sheep.'),
  ('veron', 'Veron', 3, 'veron_castle', 'Sheep', 421.0, 'Veron is a village of the Western Empire owned by Achios of the Corenios. The village is bound to Veron Castle and it is know for the production of Sheep.');
